package com.example.taskmanager.service; import com.example.taskmanager.model.Task; import org.springframework.stereotype.Service; import java.time.*;
@Service public class PriorityService { public void calculate(Task t){ long hours=Math.max(0,Duration.between(LocalDateTime.now(),t.getDeadline()).toHours()); double urgency=hours<=6?100:hours<=24?90:hours<=72?70:hours<=168?50:25; double importance=Math.min(100,t.getImportance()*20.0); double effort=t.getEstimatedHours()<=2?90:t.getEstimatedHours()<=4?75:t.getEstimatedHours()<=8?55:35; int score=(int)Math.round(urgency*.50+importance*.35+effort*.15); t.setPriorityScore(score); t.setPriority(score>=75?"HIGH":score>=50?"MEDIUM":"LOW"); } }
